import fs from 'node:fs/promises';import{db}from'./reply-runtime-20261015.mjs';import{deliveryExposure}from'./realtor-delivery-exposure-20261019.mjs';
const dir='artifacts/realtor-batch-20261019';const live=JSON.parse(await fs.readFile(dir+'/live-status.json'));if(Date.parse(live.summary.at)<Date.now()-120000)throw Error('Refresh receipts');const exposure=deliveryExposure(live.jobs,live.events,2000);const excess=Math.max(0,exposure.delivered+exposure.unresolved-2000);
const candidates=live.jobs.filter(j=>j.status==='pending'&&!j.provider_sid).sort((a,b)=>b.scheduled_at.localeCompare(a.scheduled_at));const result=[];
for(const j of candidates){if(result.length>=excess)break;const reservations=await db('partnership_action_reservations',{action_key:'eq.sequence:'+j.id,select:'action_key'});if(reservations.length)continue;const rows=await db('sequence_jobs',{id:'eq.'+j.id,status:'eq.pending',provider_sid:'is.null'},'PATCH',{status:'cancelled',error:'Cancelled untouched excess queue to preserve 2,000 delivery exposure limit',last_error:'excess_exposure_cancelled_20261019'});if(rows.length===1)result.push({id:j.id,contact_id:j.contact_id});}
await fs.writeFile(dir+'/exposure-correction-'+Date.now()+'.json',JSON.stringify({at:new Date().toISOString(),before:exposure,excess,cancelled:result},null,2));console.log(JSON.stringify({excess,cancelled:result.length}));if(result.length!==excess)throw Error('Could not cancel full excess; fresh review required');
